#include <stdio.h>

int sum_from(int fish[], int start, int count) {
    int sum = 0;
    for (int i = start; i < count; i++) {
        sum += fish[i];
        printf("第 %d 轮：sum = %d\n", i + 1, sum);
    }
    return sum;
}

int main(void) {
    int fish[4] = { {a}, {b}, {c}, {d} };
    printf("总数是 %d\n", sum_from(fish, 0, 4));
    return 0;
}
